class Solution:
    def threeSum(self, nums: list[int]) -> list[list[int]]:
        nums.sort()
        triples: list[list[int]] = []
        for i in range(len(nums) - 2):
            if i > 0 and nums[i] == nums[i - 1]:
                continue  # viz:skip_i
            l, r = i + 1, len(nums) - 1  # viz:fix
            while l < r:
                total = nums[i] + nums[l] + nums[r]
                if total < 0:
                    l += 1  # viz:move_l
                elif total > 0:
                    r -= 1  # viz:move_r
                else:
                    triples.append([nums[i], nums[l], nums[r]])  # viz:found
                    l += 1
                    r -= 1
                    while l < r and nums[l] == nums[l - 1]:
                        l += 1  # viz:skip_l
        return triples
